Read file /Users/ajeet/Projects/Hackathons/Sheridan Datathon 2026/src/lib/format.ts, lines 1-44
1: import type { RunwayState } from './shocks'
2: 
3: const CAD_FORMAT = new Intl.NumberFormat('en-CA', {
4:   style: 'currency',
5:   currency: 'CAD',
6: })
7: 
8: /**
9:  * Format integer CAD cents as a dollar string (for example $1,234.56).
10:  * Negative cents keep their numeric minus in front of the symbol
11:  * (for example -$1,234.50), which is the one allowed dash in shipped
12:  * strings because it is a formatted number, not prose. Non finite input
13:  * reads n/a instead of printing NaN on a card.
14:  */
15: export function formatCents(cents: number): string {
16:   if (!Number.isFinite(cents)) {
17:     return 'n/a'
18:   }
19:   return CAD_FORMAT.format(cents / 100)
20: }
21: 
22: /**
23:  * Format tenths of a month for the runway readouts: 98 reads 9.8 months,
24:  * the no_shortfall cap reads 120+ months, and a depleted buffer reads
25:  * 0.0 months. The state wins over the number so the two special states
26:  * can never print as an ordinary figure.
27:  */
28: export function formatDeciMonths(deciMonths: number, state: RunwayState): string {
29:   if (state === 'no_shortfall') {
30:     return '120+ months'
31:   }
32:   if (state === 'buffer_depleted') {
33:     return '0.0 months'
34:   }
35:   if (!Number.isFinite(deciMonths)) {
36:     return 'n/a months'
37:   }
38:   return `${(deciMonths / 10).toFixed(1)} months`
39: }
40: 
41: /** Format an m/s budget for the HUD (one decimal, for example 1641.5 m/s). */
42: export function formatMetersPerSecond(value: number): string {
43:   return `${value.toFixed(1)} m/s`
44: }

